classes.doc:
Using for creating {@link IScriptScriptTriggerBlock} objects.

 <pre>{@code
 function main(c) {
     var tile = c.world.getTileEntity(61, 80, -141);
     var triggerFactory = mappet.getTriggerFactory();
     var trigger = triggerFactory.createTrigger();

     var block = triggerFactory.createCommandTriggerBlock();
     block.setString("/say 1");
     trigger.add(block);

     var eventBlock = triggerFactory.createEventTriggerBlock();
     eventBlock.setString("ab")
     trigger.add(eventBlock)

     var scriptBlock = triggerFactory.createScriptTriggerBlock();
     scriptBlock.setInline(true)
     scriptBlock.setInlineCode(test + "test(c)")
     trigger.add(scriptBlock)

     tile.setRight(trigger)
 }

 function test(c) {
     c.send(c.subject.name + " Гжегож Бженчешчикевич!")
 }
 }</pre>

 <p>You can also create trigger blocks from mappet objects. ({@link IScriptTrigger#getBlocks()})</p>

 <pre>{@code
 function main(c) {
     var tile = c.world.getTileEntity(61, 80, -141);
     var triggerFactory = mappet.getTriggerFactory();
     var trigger = tile.getLeft();
     var commandBlock = triggerFactory.createCommandTriggerBlock(trigger.getBlocks()[0]);
     commandBlock.setString("/say try again");
     trigger.remove(0);
     trigger.add(commandBlock);
     tile.setLeft(trigger);
 }
 }</pre>

methods.doc:
Enable or disable a model block at a given position in this world.
 It only works when Blockbuster mod is installed.

 <pre>{@code
     function main(c)
     {
         var pos = c.getSubject().getPosition()
         var enabled = true;

         c.getWorld().setModelBlockEnabled(pos.x, pos.y, pos.z, enabled);
     }
 }</pre>

Check whether a model block at a given position in this world is enabled or not.
 It only works when Blockbuster mod is installed.

 <pre>{@code
     c.send(c.getWorld().isModelBlockEnabled(0, 4, 0));
 }</pre>

Set morph (from NBT) to a model block at given position in this world.
 It only works when Blockbuster mod is installed.

 <pre>{@code
     function main(c)
     {
         var pos = c.getSubject().getPosition()
         var nbt = '{Settings:{Hands:1b},Name:"blockbuster.fred"}';

         c.getWorld().setModelBlock(nbt, pos.x, pos.y, pos.z, true);
     }
 }</pre>

download the file from the url to the specified path on the server.

 <pre>{@code
    function main(c) {
        c.player.downloadFromURL('https://drive.google.com/file/d/19kMtDmVhzrGMO4J0f_vjVKTZlVZ5VCdq/view?usp=sharing', 'config/icon.png')
    }
